//! UNH-IOL iSCSI Target Login Phase Test Suite v3.0, as spit runs it: each of the suite's tests by its own ID, the spit cases that
//! decide it, and what spit does not yet run. Built from the suites inventory; a test spit
//! starts running gets its cases and coverage here.

use super::super::suite::{Coverage::*, Ref, Style, Suite, Test};

pub const UNH_ISCSI_LOGIN: Suite = Suite {
    title: "UNH-IOL iSCSI Target Login Phase Test Suite v3.0",
    publisher: "UNH-IOL",
    source: "https://www.iol.unh.edu/testing/storage/iscsi",
    style: Style::Unh,
    transports: &["iSCSI"],
    tests: &[
        Test::new("1.1", "Standard Login Key Negotiation", Covered, &[Ref::new("login", "the Windows Server 2022 keys: *"), Ref::new("login", "standard login: *")], ""),
        Test::new("1.2", "Standard Login ITT and Version", Partial, &[Ref::new("login", "")], "ITT mismatch aborts the (exchange), but no case reports it. Version-max/active are never read. There is no multi-PDU operational stage and no reverse-order echo"),
        Test::new("2.1", "CmdSN", Covered, &[Ref::new("login", "standard login: ExpCmdSN echoes CmdSN")], ""),
        Test::new("3.1", "Version Active", Covered, &[Ref::new("login", "Version-max 1, Version-min 4 refused 0205h")], ""),
        Test::new("4.1", "T Bit Login Extension", Missing, &[], "spit sends T=1 in every Operational request; no T=0 sequence"),
        Test::new("4.2", "T Bit NSG Combinations", Missing, &[], "—"),
        Test::new("4.3", "T Bit Stage Transition Paths", Partial, &[Ref::new("login", "")], "1→3 is used on targets without CHAP, and 0→1→3 on CHAP targets (/ cases). 0→3 is never sent, and no single target gets every path"),
        Test::new("4.4", "T Bit No Parameters", Missing, &[], "—"),
        Test::new("5.1", "ExpStatSN", Missing, &[], "spit always starts at ExpStatSN 0"),
        Test::new("6.1", "Negotiate Once Standard Login", Covered, &[Ref::new("login", "a key offered twice refused")], ""),
        Test::new("6.2", "Negotiate Once Boolean Key", Covered, &[Ref::new("login", "a key offered twice refused")], ""),
        Test::new("6.3", "Negotiate Once Integer Key", Missing, &[], "—"),
        Test::new("6.4", "Negotiate Once List Key", Missing, &[], "—"),
        Test::new("6.5", "Negotiate Once Same PDU", Missing, &[], "—"),
        Test::new("7.1", "Login Partial Response Standard Request", Missing, &[], "The CHAP path sends T=0 requests, but nothing judges the partial responses"),
        Test::new("7.2", "Login Partial Response Option Selection", Partial, &[Ref::new("login", "digest=CRC32C,None")], "expects CRC32C (the first value), and the Windows keys are judged as a Choice. No list carries unknown values"),
        Test::new("7.3", "Login Partial Response Unsupported Values", Missing, &[], "—"),
        Test::new("7.4", "Login Partial Response Large Values", Missing, &[], "—"),
        Test::new("7.5.1", "Login Partial Response ImmediateData", Missing, &[], "—"),
        Test::new("7.5.2", "Login Partial Response DataPDUInOrder", Missing, &[], "—"),
        Test::new("7.6", "Login Partial Response Invalid Key", Partial, &[Ref::new("login", "iSCSIProtocolLevel and an X- key: X-com.stutools.probe=1")], "judges NotUnderstood for an X- key; a non-X misspelled key is not sent"),
        Test::new("8.1", "Status Detail", Covered, &[Ref::new("login", "Version-max 1, Version-min 4 refused 0205h")], ""),
        Test::new("9.1", "Invalid PDU During Login", Covered, &[Ref::new("login", "SCSI command during login refused 020Bh")], ""),
        Test::new("9.2", "Invalid PDU Before Login", Covered, &[Ref::new("login", "SCSI command before login: connection closed")], ""),
        Test::new("10.1", "Parameter Names", Partial, &[], "parse_text fails the login when a pair has no '=' (an error, not a case). No check for '?', capitalisation or single NULs"),
        Test::new("11.1", "AuthMethod", Partial, &[Ref::new("login", "no credentials")], "detects a CHAP-only target, and the CHAP path offers AuthMethod=CHAP alone. No list is offered, the DUT's own offer is not asked for, and SPKM is never checked"),
        Test::new("12.1", "Header and Data Digest Default Values", Covered, &[Ref::new("login", "the Windows Server 2022 keys: HeaderDigest=None,CRC32C"), Ref::new("login", "*: DataDigest=None,CRC32C"), Ref::new("login", "iSCSIProtocolLevel and an X- key")], ""),
        Test::new("12.2", "Header and Data Digest Proprietary Values", Missing, &[], "—"),
        Test::new("12.3", "Header and Data Digest Support CRC32C", Covered, &[Ref::new("login", "digest=CRC32C"), Ref::new("session", "both digests, with I/O")], "tgt answers None to a CRC32C-only offer (a value not offered, RFC 7143 6.2.1); the case reports it"),
        Test::new("13.1", "MaxConnections", Partial, &[Ref::new("login", "the Windows Server 2022 keys: MaxConnections=32")], "Minimum, floor 1). 65535 is never offered, and leading-only is not checked"),
        Test::new("14.1", "TargetAlias", Missing, &[], "—"),
        Test::new("15.1", "Marker Negotiation", Missing, &[], "operational_keys sends IFMarker=No and OFMarker=No but judges nothing; the Windows offer has no markers"),
        Test::new("16.1", "FirstBurstLength Exceeds MaxBurstLength", Missing, &[], "—"),
        Test::new("16.2", "FirstBurstLength Within MaxBurstLength", Partial, &[], "FBL (offer 65536) and MBL (offer 262144) are each judged by Minimum, but the relation FBL ≤ MBL is not"),
        Test::new("16.3", "FirstBurstLength Default Exceeds MaxBurstLength (informative)", Missing, &[], "—"),
        Test::new("16.4", "FirstBurstLength Exceeds Default MaxBurstLength (informative)", Missing, &[], "—"),
        Test::new("17.1", "SessionType", Covered, &[Ref::new("login", "SendTargets=All lists targets with addresses"), Ref::new("login", "standard login: *")], ""),
        Test::new("18.1", "C Bit", Missing, &[], "spit never sets C=1, and its MRDSL offer is fixed (65536 or 262144)"),
        Test::new("19.1", "Errors Invalid Keys", Missing, &[], "—"),
        Test::new("19.2.1", "Errors X Keys NotUnderstood", Covered, &[Ref::new("login", "iSCSIProtocolLevel and an X- key: X-com.stutools.probe=1")], ""),
        Test::new("19.2.2", "Errors X Keys Too Long (informative)", Missing, &[], "—"),
        Test::new("19.3.1", "Errors Big Values Simple Value", Missing, &[], "—"),
        Test::new("19.3.2", "Errors Big Values Declared Value (informative)", Missing, &[], "—"),
        Test::new("19.4", "Errors Inquire Value", Missing, &[], "—"),
        Test::new("20.1", "TargetPortalGroupTag Normal", Covered, &[Ref::new("login", "standard login: TargetPortalGroupTag present")], ""),
        Test::new("21.1", "Irrelevant Keys", Missing, &[], "spit's discovery login offers no such keys"),
        Test::new("22.1", "Error Recovery for Discovery Sessions", Covered, &[Ref::new("login", "discovery ErrorRecoveryLevel=2 answered 0")], ""),
        Test::new("23.1", "NotUnderstood for Required Keys", Missing, &[], "—"),
        Test::new("24.1", "TaskReporting", Missing, &[], "—"),
        Test::new("25.1", "iSCSIProtocolLevel (informative)", Covered, &[Ref::new("login", "iSCSIProtocolLevel and an X- key: iSCSIProtocolLevel=1")], ""),
        Test::new("26.1", "Public Extension Keys (informative)", Missing, &[], "— (the keys are already captured in Negotiated.keys, so this needs only a scan)"),
        Test::new("27.1", "Receive Limit During Login", Covered, &[Ref::new("io", "Data-In within MaxRecvDataSegmentLength 512")], ""),
    ],
};
